interface File extends Blob {
  readonly name: string;
}

async uploadFile(file: File, headers: object): Promise<any> {
  // Step 1 — get the pre-signed POST (url + fields)
  const presignedPost = await this.getSignedUrl();

  const data = new FormData();
  // Append every field returned by Step 1 ...
  Object.entries(presignedPost.fields).forEach(([field, value]) => {
    data.append(field, value);
  });
  // ... then append the file LAST.
  data.append('file', file, file?.name);

  // Headers must include 'Content-Type': 'multipart/form-data'
  return this.http.post(presignedPost.url, data, headers);
}

